// Works for both Chat app types: "Workspace add-on" events (body.chat) and classic Chat API events (body.type).
const body = $json.body || {};
const allowed = String($json.allowed_chat_users || '').toLowerCase().split(',').map((s) => s.trim()).filter(Boolean);
const addon = !!body.chat;
let kind, text, email;
if (addon) {
  const p = body.chat.messagePayload;
  kind = p ? 'message' : body.chat.addedToSpacePayload ? 'added' : 'other';
  text = p ? (p.message.argumentText || p.message.text || '') : '';
  email = (body.chat.user && body.chat.user.email) || (p && p.message.sender && p.message.sender.email) || '';
} else {
  kind = body.type === 'MESSAGE' ? 'message' : body.type === 'ADDED_TO_SPACE' ? 'added' : 'other';
  text = (body.message && (body.message.argumentText || body.message.text)) || '';
  email = (body.user && body.user.email) || '';
}
const wrap = (t) => (addon ? { hostAppDataAction: { chatDataAction: { createMessageAction: { message: { text: t } } } } } : { text: t });
const help = 'Write who and which month, for example "Aoba, September" or "Blue Harbor の先月分". I create a Gmail draft with the PDF; nothing is sent.';
let reply = null;
if (kind !== 'message') reply = wrap(help);
else if (!allowed.includes(String(email).toLowerCase())) reply = wrap('Sorry, ' + (email || 'this account') + ' is not on the list of people who can create invoices.');
else if (!text.trim()) reply = wrap(help);
return [{ json: { ok: !reply, reply, Request: text.trim(), source: 'chat', addon, sender: email } }];

// Turn the three tabs into lists of rows keyed by the header row.
const ranges = $json.valueRanges || [];
const table = (name) => {
  const r = ranges.find((v) => String(v.range || '').replace(/^'/, '').startsWith(name + '!'));
  const rows = (r && r.values) || [];
  const head = (rows[0] || []).map((h) => String(h).trim());
  return rows.slice(1)
    .filter((row) => row.some((c) => String(c).trim() !== ''))
    .map((row) => Object.fromEntries(head.map((h, i) => [h, row[i] ?? ''])));
};
const customers = table('Customers');
const items = table('Items');
const invoices = table('Invoices');
if (!customers.length) throw new Error('The Customers tab is empty or missing. Check spreadsheet_id in Config and the tab names (Customers, Items, Invoices).');
return [{ json: { customers, items, invoices } }];

