// Code checks what Claude read against the request and the customer list. The month is computed here from the words.
const cfg = $('Config').first().json;
const request = String(cfg.request || '').trim();
const { customers } = $('Parse the sheets').first().json;
let r;
try { r = JSON.parse(String($json.text ?? '').match(/\{[\s\S]*\}/)[0]); }
catch (e) { return [{ json: { ok: false, problem: 'Could not read the AI answer as JSON. Try again or write the request more simply.' } }]; }
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFKC').replace(/\s+/g, ' ').trim();
const req = norm(request);
const problems = [];
const today = DateTime.now().setZone(cfg.timezone);

const cust = customers.find((c) => String(c.customer_id).trim() === r.customer_id);
if (!r.customer_id) problems.push('The request does not name a customer from the Customers tab.');
else if (!cust) problems.push('"' + r.customer_id + '" is not a customer_id in the Customers tab.');
else {
  const words = norm(r.customer_words);
  const names = [cust.name, ...String(cust.other_names || '').split(',')].map(norm).filter(Boolean);
  if (!words || !req.includes(words)) problems.push('The customer words "' + (r.customer_words ?? '') + '" are not in the request.');
  else if (!names.some((nm) => nm.includes(words) || words.includes(nm))) problems.push('"' + r.customer_words + '" does not match ' + cust.name + ' or its other names.');
}

const monthNames = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const pick = (mm) => { let y = today.year; if (mm > today.month) y -= 1; return y + '-' + String(mm).padStart(2, '0'); };
function monthFromWords(w) {
  const s = norm(w);
  let m;
  if ((m = s.match(/(\d{4})\s*[-\/年.]\s*(\d{1,2})/))) return m[1] + '-' + m[2].padStart(2, '0');
  if ((m = s.match(/(\d{1,2})\s*月/))) return pick(Number(m[1]));
  for (let i = 0; i < 12; i++) if (s.includes(monthNames[i]) || new RegExp('\\b' + monthNames[i].slice(0, 3) + '\\b').test(s)) return pick(i + 1);
  if (/先月|前月|last month/.test(s)) return today.minus({ months: 1 }).toFormat('yyyy-MM');
  if (/今月|this month/.test(s)) return today.toFormat('yyyy-MM');
  return null;
}
if (!r.month_words) problems.push('The request does not say which month. Write it, for example "September", "9月" or "2026-09".');
else if (!req.includes(norm(r.month_words))) problems.push('The month words "' + r.month_words + '" are not in the request.');
else {
  const m = monthFromWords(r.month_words);
  if (!m) problems.push('Could not read a month from "' + r.month_words + '".');
  else if (m !== r.month) problems.push('The AI read the month as ' + r.month + ', but "' + r.month_words + '" means ' + m + '.');
  else if (m > today.toFormat('yyyy-MM')) problems.push(m + ' is in the future.');
}
return [{ json: { ok: problems.length === 0, problem: problems.join(' '), customer_id: r.customer_id, month: r.month, read: r } }];

// Code finds the lines, computes every amount and date, and prepares the text for the template.
const cfg = $('Config').first().json;
const { customers, items, invoices } = $('Parse the sheets').first().json;
const { customer_id, month } = $json;
const cust = customers.find((c) => String(c.customer_id).trim() === customer_id);
const toMonth = (v) => {
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + v * 86400000).toISOString().slice(0, 7);
  const m = String(v).trim().match(/^(\d{4})[-\/](\d{1,2})/);
  return m ? m[1] + '-' + m[2].padStart(2, '0') : String(v).trim();
};
const num = (v) => (typeof v === 'number' ? v : Number(String(v).replace(/[,\s¥$€]/g, '')));
const lines = items.filter((i) => String(i.customer_id).trim() === customer_id && toMonth(i.month) === month);
const invoice_no = cfg.invoice_prefix + month.replace('-', '') + '-' + customer_id;
const problems = [];
if (!lines.length) problems.push('No lines for ' + cust.name + ' in ' + month + ' in the Items tab.');
if (lines.length > cfg.max_lines) problems.push(lines.length + ' lines for ' + month + ', but max_lines in Config is ' + cfg.max_lines + '. Check the Items tab, or raise max_lines.');
const bad = lines.filter((l) => !Number.isFinite(num(l.quantity)) || !Number.isFinite(num(l.unit_price)) || String(l.quantity).trim() === '' || String(l.unit_price).trim() === '');
if (bad.length) problems.push('Quantity or unit price is not a number for: ' + bad.map((b) => b.description).join(', ') + '.');
const prev = invoices.find((x) => String(x.invoice_no).trim() === invoice_no && String(x.status).trim().toLowerCase() !== 'void');
if (prev) problems.push(invoice_no + ' was already created (' + prev.created_at + '). To create it again, set its status to "void" in the Invoices tab.');
if (problems.length) return [{ json: { ok: false, problem: problems.join(' ') } }];

const dec = Number(cfg.currency_decimals);
const roundTo = (x, mode) => { const f = 10 ** dec; const v = x * f; const r = mode === 'floor' ? Math.floor(v + 1e-9) : mode === 'ceil' ? Math.ceil(v - 1e-9) : Math.round(v); return r / f; };
const fmt = (x) => new Intl.NumberFormat(cfg.number_locale, { style: 'currency', currency: cfg.currency, minimumFractionDigits: dec, maximumFractionDigits: dec }).format(x);
const rows = lines.map((l) => { const q = num(l.quantity); const p = num(l.unit_price); return { description: String(l.description), q, p, amount: roundTo(q * p, 'round') }; });
const subtotal = roundTo(rows.reduce((s, x) => s + x.amount, 0), 'round');
const tax = roundTo(subtotal * Number(cfg.tax_rate) / 100, cfg.tax_rounding);
const total = roundTo(subtotal + tax, 'round');
const today = DateTime.now().setZone(cfg.timezone);
const terms = Number(cust.payment_terms_days) || Number(cfg.default_payment_terms_days);
const due = today.plus({ days: terms });
const start = DateTime.fromFormat(month, 'yyyy-MM', { zone: cfg.timezone });
const period = start.toFormat('yyyy-MM-dd') + ' to ' + start.endOf('month').toFormat('yyyy-MM-dd');
const values = {
  invoice_no, issue_date: today.toFormat('yyyy-MM-dd'), due_date: due.toFormat('yyyy-MM-dd'),
  customer_name: cust.name, customer_address: cust.address, period,
  subtotal: fmt(subtotal), tax_rate: cfg.tax_rate + '%', tax: fmt(tax), total: fmt(total),
  seller_name: cfg.seller_name, seller_address: cfg.seller_address, payment_details: cfg.payment_details, notes: cfg.notes,
};
// One line per item; the newlines become separate paragraphs in the document.
values.lines = rows.map((x) => x.description + '   ' + x.q + ' x ' + fmt(x.p) + ' = ' + fmt(x.amount)).join('\n');
const requests = Object.entries(values).map(([k, v]) => ({ replaceAllText: { containsText: { text: '{{' + k + '}}', matchCase: true }, replaceText: String(v ?? '') } }));
const body = String(cfg.email_body).replace(/\[(\w+)\]/g, (m, k) => (k in values ? values[k] : m));
return [{ json: {
  ok: true, invoice_no, customer_id, month, email: cust.email, values, requests,
  amounts: { subtotal, tax, total, lines: rows.length },
  subject: 'Invoice ' + invoice_no + ' from ' + cfg.seller_name, body,
  doc_name: 'Invoice ' + invoice_no + ' ' + cust.name,
} }];

// Same text as the form pages, in the shape Google Chat expects for this app type.
const addon = $('Config').first().json.addon;
let t;
if ($json.problem) t = 'Nothing was created. ' + $json.problem;
else {
  const b = $('Build the invoice').first().json;
  t = 'Draft created: ' + b.invoice_no + '\nTotal ' + b.values.total + ' (' + b.amounts.lines + ' lines). The Gmail draft to ' + b.email
    + ' has the PDF attached. Check it and send it yourself.\nDocument: https://docs.google.com/document/d/' + $('Copy the template').first().json.id + '/edit';
}
const reply = addon ? { hostAppDataAction: { chatDataAction: { createMessageAction: { message: { text: t } } } } } : { text: t };
return [{ json: { reply } }];
